package org.sleepwell.app;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;

/** Separate derived evidence; raw epochs, audio and user edits are never rewritten. */
final class EchoPeriods {
    static final Set<String> QUALITY=Set.of("PERIODIC","INSUFFICIENT_SIGNAL","NO_STABLE_PERIOD","AMBIGUOUS");
    static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE echo_runs(session INTEGER PRIMARY KEY,enabled INTEGER NOT NULL,algorithm TEXT NOT NULL,state TEXT NOT NULL)");db.execSQL("CREATE TABLE echo_periods(id INTEGER PRIMARY KEY,session INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,rate REAL,periodicity REAL NOT NULL,quality TEXT NOT NULL)");db.execSQL("CREATE INDEX echo_period_session ON echo_periods(session,start)");db.execSQL("CREATE TRIGGER delete_echo_record AFTER DELETE ON sessions BEGIN DELETE FROM echo_periods WHERE session=OLD.id; DELETE FROM echo_runs WHERE session=OLD.id; END");}
    static void begin(Store store,long id,boolean enabled){ContentValues v=new ContentValues();v.put("session",id);v.put("enabled",enabled?1:0);v.put("algorithm",EchoPeriodicity.ALGORITHM);v.put("state",enabled?"active":"off");store.getWritableDatabase().insertOrThrow("echo_runs",null,v);}
    static void append(Store store,long id,long from,long to,Double rate,double correlation,String quality){
        validateWindow(from,to,rate,correlation,quality);List<JSONObject> found=store.rows("SELECT s.start,s.end,r.state FROM sessions s JOIN echo_runs r ON r.session=s.id WHERE s.id=? AND s.sensor=? AND r.enabled=1",Long.toString(id),SensorProvenance.SONAR);if(found.size()!=1||!found.get(0).isNull("end")||!found.get(0).optString("state").equals("active")||from<found.get(0).optLong("start"))throw new IllegalStateException("Periodic echo recording changed.");
        List<JSONObject> previous=store.rows("SELECT MAX(end) AS end FROM echo_periods WHERE session=?",Long.toString(id));if(!previous.get(0).isNull("end")&&from<previous.get(0).optLong("end"))throw new IllegalArgumentException("Overlapping periodic echo windows.");ContentValues v=new ContentValues();v.put("session",id);v.put("start",from);v.put("end",to);v.put("rate",rate);v.put("periodicity",correlation);v.put("quality",quality);store.getWritableDatabase().insertOrThrow("echo_periods",null,v);
    }
    static void end(Store store,long id,boolean interrupted){store.getWritableDatabase().execSQL("UPDATE echo_runs SET state=? WHERE session=? AND state='active'",new Object[]{interrupted?"interrupted":"complete",id});}
    static void recover(SQLiteDatabase db,long id){db.execSQL("UPDATE echo_runs SET state='interrupted' WHERE session=? AND state='active'",new Object[]{id});}
    static void validateWindow(long from,long to,Double rate,double correlation,String quality){if(from<=0||to-from!=EchoPeriodicity.WINDOW||!Double.isFinite(correlation)||correlation<0||correlation>1||!QUALITY.contains(quality)||quality.equals("PERIODIC")!=(rate!=null)||rate!=null&&(!Double.isFinite(rate)||rate<5||rate>40))throw new IllegalArgumentException("Invalid periodic echo window.");}
    static void export(Store store,JSONObject root)throws JSONException{root.put("echo_runs",new JSONArray(store.rows("SELECT * FROM echo_runs"))).put("echo_periods",new JSONArray(store.rows("SELECT * FROM echo_periods")));validate(root);}
    static void validate(JSONObject root)throws JSONException{
        JSONArray ss=root.getJSONArray("sessions"),rr=root.getJSONArray("echo_runs"),pp=root.getJSONArray("echo_periods");if(rr.length()>100000||pp.length()>100000)throw new JSONException("Too much periodic echo evidence");Map<Long,JSONObject> sessions=new HashMap<>(),runs=new HashMap<>();for(int n=0;n<ss.length();n++){JSONObject s=ss.getJSONObject(n);sessions.put(SensorProvenance.whole(s,"id"),s);}
        for(int n=0;n<rr.length();n++){JSONObject r=rr.getJSONObject(n);long id=SensorProvenance.whole(r,"session"),enabled=SensorProvenance.whole(r,"enabled");String state=SensorProvenance.text(r,"state");JSONObject s=sessions.get(id);if(r.length()!=4||s==null||runs.put(id,r)!=null||!SensorProvenance.SONAR.equals(s.optString("sensor"))||!"tracked".equals(s.optString("source"))||!EchoPeriodicity.ALGORITHM.equals(SensorProvenance.text(r,"algorithm"))||enabled<0||enabled>1||!Set.of("off","active","complete","interrupted").contains(state)||enabled==0&&!state.equals("off")||enabled==1&&state.equals("off")||!s.isNull("end")&&state.equals("active"))throw new JSONException("Invalid periodic echo run");}
        Set<Long> ids=new HashSet<>();Map<Long,List<JSONObject>> grouped=new HashMap<>();for(int n=0;n<pp.length();n++){JSONObject p=pp.getJSONObject(n);long id=SensorProvenance.whole(p,"id"),session=SensorProvenance.whole(p,"session"),from=SensorProvenance.whole(p,"start"),to=SensorProvenance.whole(p,"end");JSONObject s=sessions.get(session),run=runs.get(session);Double rate=p.isNull("rate")?null:SensorProvenance.number(p,"rate");double periodicity=SensorProvenance.number(p,"periodicity");String quality=SensorProvenance.text(p,"quality");try{validateWindow(from,to,rate,periodicity,quality);}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}if(p.length()!=7||!p.has("rate")||id<=0||!ids.add(id)||s==null||run==null||run.getInt("enabled")!=1||from<s.getLong("start")||to-s.getLong("start")>SensorProvenance.MAX_SESSION||!s.isNull("end")&&to>s.getLong("end"))throw new JSONException("Invalid periodic echo interval");grouped.computeIfAbsent(session,k->new ArrayList<>()).add(p);}
        for(List<JSONObject> windows:grouped.values()){windows.sort(Comparator.comparingLong(w->w.optLong("start")));long end=0;for(JSONObject p:windows){if(p.getLong("start")<end)throw new JSONException("Overlapping periodic echo windows");end=p.getLong("end");}}
    }
    static void restore(Store store,JSONObject root,Runnable guard)throws JSONException{for(String table:List.of("echo_runs","echo_periods"))for(int n=0;n<root.getJSONArray(table).length();n++){guard.run();JSONObject p=root.getJSONArray(table).getJSONObject(n);ContentValues v=new ContentValues();v.put("session",p.getLong("session"));if(table.equals("echo_runs")){v.put("enabled",p.getInt("enabled"));v.put("algorithm",p.getString("algorithm"));String state=p.getString("state");v.put("state",state.equals("active")?"interrupted":state);}else{v.put("id",p.getLong("id"));v.put("start",p.getLong("start"));v.put("end",p.getLong("end"));v.put("rate",p.isNull("rate")?null:p.getDouble("rate"));v.put("periodicity",p.getDouble("periodicity"));v.put("quality",p.getString("quality"));}store.getWritableDatabase().insertOrThrow(table,null,v);}}
    private EchoPeriods(){}
}
